#include "script_engine.hh"
#include "config.h"

ScriptEngine::ScriptEngine(void * arg_r1)
{
    unk_350 = arg_r1;
    unk_354 = nullptr;
    event_context = 0;
}

ScriptEngine::ScriptEngine(void * arg_r1, void * arg_r2)
{
    unk_350 = arg_r1;
    unk_354 = arg_r2;
    event_context = 0;
}

void ScriptEngine::LoadById(int id, int context_value)
{
    Load(gMaryScriptTable[id]);
    event_context = context_value;
}

void ScriptEngine::SetUnk(void * unk)
{
    unk_354 = unk;
}

void ScriptEngine::ClearUnk()
{
    unk_354 = nullptr;
}

void ScriptEngine::Push(i32 value)
{
    stack.Push(value);
}

